import { readFile, writeFile } from "node:fs/promises";

const html = await readFile(".attachment-app-dist/index.html", "utf8");
const generated = [
  "// Generated by scripts/embed-attachment-app.mjs. Do not edit by hand.",
  "export const ATTACHMENT_UPLOADER_HTML = " + JSON.stringify(html) + ";",
  "",
].join("\n");

await writeFile("src/generated/attachment-uploader-html.ts", generated);
